import{z as l,x as B,o as r,c as m,q as t,j as i,D as e,d as n,s as E,S as s}from"./chunks/framework.C8m1ZpeB.js";const F=JSON.parse('{"title":"Rough Bergomi","description":"","frontmatter":{"title":"Rough Bergomi","date":"2026-09-07T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/rough-bergomi.md","filePath":"quant/rough-bergomi.md","lastUpdated":1791413859000}'),h={name:"quant/rough-bergomi.md"};function A(u,a,g,p,d,_){const o=B("Mermaid");return r(),m("div",null,[a[2]||(a[2]=t('<h1 id="rough-bergomi" tabindex="-1">Rough Bergomi <a class="header-anchor" href="#rough-bergomi" aria-label="Permalink to &quot;Rough Bergomi&quot;">​</a></h1><div class="epigraph"><p>把 Bergomi 远期方差曲线上的指数核换成分数核 $(T-t)^{H-1/2}$，瞬时方差的路径正则性掉到 Hurst 指数 $H$；短端偏斜因此可以很陡，却不必另加跳跃，也不必把长端 vol-of-vol 一起抬高。</p><footer>—— Bayer, Friz and Gatheral, Pricing under rough volatility, Quantitative Finance, 2016</footer></div><p><a href="/quant/ssvi-term-consistency">上一课</a>把一致性收成函数级约束；现在换一条路，让核自己粗糙。<a href="/quant/rough-vol">粗糙波动</a> 写的是经验尺度律：已实现对数波动的增量方差按 \\(\\Delta^{2H}\\) 缩放，\\(H\\) 落在 \\(0.1\\) 附近。<a href="/quant/bergomi">Bergomi</a> 写的是对象：远期方差曲线 \\(\\xi_t(u)\\) 对每个到期是鞅，今日曲线从市场填入。Christian Bayer、Peter Friz 与 Jim Gatheral 把二者接到同一条定价规格上——粗糙 Bergomi（rBergomi）：保留曲线对象，只改驱动核。本篇写这一规格、高斯 Volterra 模拟与分层校准，不把 Gatheral–Jaisson–Rosenbaum 的回归再做一遍，也不把两因子指数核的推导重写；<a href="/quant/heston">Heston</a> 的仿射特征函数在这里用不上。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>经典一因子 Bergomi 的核 \\(e^{-k(T-t)}\\) 在 \\(T\\downarrow t\\) 处有界。要把两周偏斜做陡，只能抬整个曲线的 vol-of-vol，一年方差互换就会被搅过头；两因子把能量按期限切开，但仍是半鞅扩散，短尺度正则性是 \\(H=1/2\\)。市场短端偏斜的爆破速度要求更糙的核。问题是：能否在<strong>不破坏</strong>「每个 \\(\\xi_t(u)\\) 为鞅、今日 \\(\\xi_0\\) 等于市场」的前提下，把核换成分数的，并使欧式与 <a href="/quant/vix-futures">VIX 期货</a> 仍可计算。</p><p>Bayer–Friz–Gatheral 的回答是对数正态 Volterra：用一条分数布朗（Mandelbrot–Van Ness）驱动整条曲线，瞬时方差 \\(v_t=\\xi_t(t)\\) 几乎处处只 Hölder-\\(H\\)。可交易的价格过程仍是半鞅；非半鞅的是潜在方差路径。于是无套利定价不需要新的测度论，需要的是一条能模拟的高斯过程，以及不把 \\(H\\) 交给香草去自由漂的校准纪律。</p><h3 id="分数核如何同时服务短端与长端" tabindex="-1">分数核如何同时服务短端与长端 <a class="header-anchor" href="#分数核如何同时服务短端与长端" aria-label="Permalink to &quot;分数核如何同时服务短端与长端&quot;">​</a></h3><p>核 \\(K(u,s)=(u-s)^{H-1/2}\\) 在 \\(H\\lt 1/2\\) 时于对角线发散：刚刚发生的冲击对近端 \\(\\xi\\) 极度敏感，远端核平方可积、冲击被稀释。同一 \\(\\eta\\) 因而可以同时给出陡的短偏斜与相对平静的长方差——这是一因子 rBergomi 相对两因子经典 Bergomi 的结构性优势，不是「少了一个因子却多了一个字母」。Fukasawa 把短端偏斜对 \\(\\sqrt{T}\\) 的发散阶与 \\(H\\) 连起来：Heston 有效 \\(H=1/2\\)，短端永远嫌不够陡；把 \\(H\\) 放到 \\(0.1\\)，阶就对上了。</p>',8)),(r(),i(s,null,{default:e(()=>[E(o,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20K%5B%22%E5%88%86%E6%95%B0%E6%A0%B8%20K(u%2Cs)%20%3D%20(u-s)%5E(H-1%2F2)%EF%BC%8CH%20%E2%89%88%200.1%22%5D%20--%3E%7C%22u%20%E8%B4%B4%E8%BF%91%20s%EF%BC%9A%E5%AF%B9%E8%A7%92%E7%BA%BF%E5%8F%91%E6%95%A3%22%7C%20NEAR%5B%22%E8%BF%91%E7%AB%AF%E6%9E%81%E6%95%8F%E6%84%9F%EF%BC%9A%E4%B8%A4%E5%91%A8%E5%81%8F%E6%96%9C%E5%8F%AF%E4%BB%A5%E5%81%9A%E9%99%A1%22%5D%0A%20%20K%20--%3E%7C%22u%20%E8%BF%9C%E7%A6%BB%20s%EF%BC%9A%E5%B9%B3%E6%96%B9%E5%8F%AF%E7%A7%AF%22%7C%20FAR%5B%22%E8%BF%9C%E7%AB%AF%E5%86%B2%E5%87%BB%E8%A2%AB%E7%A8%80%E9%87%8A%EF%BC%9A%E4%B8%80%E5%B9%B4%E6%96%B9%E5%B7%AE%E4%BF%9D%E6%8C%81%E5%B9%B3%E9%9D%99%22%5D%0A%20%20NEAR%20--%3E%20EFF%5B%22%E5%90%8C%E4%B8%80%E4%B8%AA%20%CE%B7%20%E5%90%8C%E6%97%B6%E8%A6%86%E7%9B%96%E7%9F%AD%E9%99%A1%E4%B8%8E%E9%95%BF%E7%A8%B3%22%5D%0A%20%20FAR%20--%3E%20EFF%0A%20%20NEAR%20--%3E%20CMP%5B%22%E6%8D%A2%E6%88%90%20Heston%EF%BC%88H%3D1%2F2%EF%BC%89%EF%BC%9A%E5%8F%AA%E8%83%BD%E6%95%B4%E4%BD%93%E6%8A%AC%20vol-of-vol%EF%BC%8C%E9%95%BF%E7%AB%AF%E8%A2%AB%E6%90%85%E8%BF%87%E5%A4%B4%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t('<p><span class="marginnote">尺度律代个数：增量方差按 \\(\\Delta^{2H}\\) 缩放，取 \\(H=0.1\\) 时，把观察间隔缩到原来的 1/100，增量方差只缩小 \\(100^{-0.2}\\approx 0.4\\) 倍——普通布朗（\\(H=1/2\\)）则会缩到 1/100。间隔越短方差相对越大，这就是「粗糙」的定量含义。</span></p><p><span class="marginnote">rBergomi 不是「Heston 加上分数布朗」。Heston 的状态是一维马尔可夫 CIR；rBergomi 的状态是整条曲线加一条非马尔可夫噪声。没有 Riccati，也没有 Feller 条件可检查。把五参数习惯套过来，会把 \\(\\xi_0\\) 误当成 \\(v_0\\)。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>令 \\(\\xi_0(u)\\) 由市场方差互换或香草条带输入，见 <a href="/quant/var-swap-replication">方差互换复制</a>。风险中性下</p> \\[\\xi_t(u)=\\xi_0(u)\\exp\\Biggl(\\eta\\sqrt{2H}\\int_0^t (u-s)^{H-1/2}\\,\\mathrm{d}W_s-\\frac{\\eta^2}{2}\\bigl[u^{2H}-(u-t)^{2H}\\bigr]\\Biggr), \\]<p>现货 \\(\\mathrm{d}S_t/S_t=\\sqrt{\\xi_t(t)}\\,\\mathrm{d}Z_t\\)，\\(\\mathrm{d}\\langle W,Z\\rangle=\\rho\\,\\mathrm{d}t\\)。指数里的积分是对 Volterra 核的 Wiener 积分：固定 \\(t\\)，映射 \\(u\\mapsto\\log\\xi_t(u)\\) 是高斯场，协方差由核的 \\(L^2\\) 内积给出。对角线 \\(u=t\\) 给出瞬时方差；定价欧式只需这条对角线的积分，定价 VIX 还需要未来三十天线的积分。</p><p><strong>模拟。</strong> 一次生成一组基准到期上的高斯向量，Cholesky 或 circulant 嵌入分解协方差，再取指数。Bayer–Friz–Gatheral 给出混合布朗方案：把核在每个时间步拆成「奇性近端」与「光滑远端」，近端用精确的高斯增量，远端用左点或混合 Riemann。后续 Bennedsen–Lunde–Pakkanen 的 hybrid scheme 把这一拆法标准化，弱收敛阶高于朴素 Euler。步长、基准到期与核截断必须与校准规格绑定：香草用细核、障碍用粗核，会制造假的模型风险。</p><p><strong>校准分层。</strong> \\(\\xi_0\\) 不参与香草最小二乘。\\(H\\) 优先用已实现方差的尺度律钉住或放在窄先验（例如 \\([0.05,0.15]\\)）；\\(\\eta,\\rho\\) 拟合偏斜期限结构。把 \\(H\\) 完全交给香草，优化器会把它推向短端过拟合，与时间序列冲突。这与经典 Bergomi「曲线给方差、相关给偏斜」同一纪律，只是多了一个不可自由漂的正则性参数。</p><p><span class="marginnote">初学者容易把今日瞬时方差 \\(v_0=\\xi_0(0)\\) 当成全部输入：rBergomi 吃的是每个未来日期 \\(u\\) 各自的远期方差 \\(\\xi_0(u)\\)，要整条方差互换曲线读进来。只塞一个数，等于把期限结构压扁成一点，长端香草必然校不上。</span></p><h3 id="与粗糙-heston、经典-bergomi-的计算分工" tabindex="-1">与粗糙 Heston、经典 Bergomi 的计算分工 <a class="header-anchor" href="#与粗糙-heston、经典-bergomi-的计算分工" aria-label="Permalink to &quot;与粗糙 Heston、经典 Bergomi 的计算分工&quot;">​</a></h3><p>粗糙 Heston（El Euch–Gatheral–Rosenbaum）用分数 Riccati 恢复特征函数，欧式可走 <a href="/quant/carr-madan">Carr–Madan</a> 一类积分，适合要快速重定价的香草账；方差曲线形状被仿射结构锁住，不如 rBergomi 自由。经典两因子 Bergomi 在长端、方差账上仍常用，因为指数核便宜、对冲桶是「短方差 / 长方差」交易员语言。生产折中常见：短端用 rBergomi 或跳解释陡偏斜，长端用经典 Bergomi 或 <a href="/quant/local-stoch-vol">局部随机波动</a> 补香草残差。不要指望一条 rBergomi 同时取代 Heston 校准速度与 Bergomi 曲线叙事。</p>',11)),(r(),i(s,null,{default:e(()=>[E(o,{id:"mermaid-54",class:"mermaid",graph:"flowchart%20TD%0A%20%20Xi0%5B%22%E5%B8%82%E5%9C%BA%20%CE%BE_0(u)%22%5D%20--%3E%20RB%5B%22rBergomi%20%E5%88%86%E6%95%B0%E6%A0%B8%22%5D%0A%20%20H%5B%22Hurst%20H%20%E6%97%B6%E9%97%B4%E5%BA%8F%E5%88%97%E5%85%88%E9%AA%8C%22%5D%20--%3E%20RB%0A%20%20Eta%5B%22%CE%B7%2C%20%CF%81%20%E6%8B%9F%E5%90%88%E5%81%8F%E6%96%9C%22%5D%20--%3E%20RB%0A%20%20RB%20--%3E%20Sim%5B%22Volterra%20%2F%20hybrid%20%E6%A8%A1%E6%8B%9F%22%5D%0A%20%20Sim%20--%3E%20EU%5B%22%E6%AC%A7%E5%BC%8F%3A%20%E6%97%A0%E7%89%B9%E5%BE%81%E5%87%BD%E6%95%B0%22%5D%0A%20%20Sim%20--%3E%20VIX%5B%22VIX%3A%20%E6%9C%AA%E6%9D%A5%E4%B8%89%E5%8D%81%E5%A4%A9%20%E2%88%9A%E2%88%AB%CE%BE%22%5D%0A%20%20Sim%20--%3E%20Path%5B%22%E8%B7%AF%E5%BE%84%E4%BA%A7%E5%93%81%3A%20%E9%9D%9E%E9%A9%AC%E5%B0%94%E5%8F%AF%E5%A4%AB%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[n(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>分数布朗 \\(W^H\\) 的协方差使短间隔增量均方正比于 \\(|\\Delta|^{2H}\\)。注入 \\(\\log\\xi\\) 之后，\\(v_t\\) 的二次变差在无穷小尺度上比半鞅更凶。对冲意义上，Gamma 误差不再是经典的 \\(\\tfrac12\\Gamma S^2(\\sigma^2-\\sigma_{\\mathrm{imp}}^2)\\Delta t\\) 加上普通离散项：方差本身的粗糙性要求更短的再平衡，才能达到与 Heston 相同的残差——这与 <a href="/quant/gamma-scalping-pnl">Gamma scalping</a> 的 PnL 恒等式兼容，只是「已实现」那一侧更噪。聚类（日、周自相关为正）与粗糙（无穷小正则性）不是同一句话；可以同时有糙的短路径与慢的长因子。</p><p><span class="marginnote">\\(H\\) 可以类比地形的「碎程度」：\\(H=1/2\\) 是缓坡丘陵（布朗运动），\\(H\\) 越接近 0 地形越像锯齿碎石——放大任何一小段都是新的锯齿。波动率路径 \\(H\\approx 0.1\\) 的意思是：方差曲线比布朗运动还毛糙，再平衡不够频繁，对冲残差就压不下去。</span></p><p>无套利要求可交易资产为半鞅。rBergomi 把方差互换曲线写成鞅 \\(\\xi_t(u)\\)，现货写成 \\(v_t\\) 驱动的积分，价格仍半鞅。攻击的是马尔可夫扩散习惯，不是风险中性定价。这也解释了为何不能对 \\(W^H\\) 本身做 Itô 交易：\\(H\\neq 1/2\\) 时它不是半鞅，可交易的是 \\(\\xi\\) 与 \\(S\\)。</p><h3 id="模拟规格即模型规格" tabindex="-1">模拟规格即模型规格 <a class="header-anchor" href="#模拟规格即模型规格" aria-label="Permalink to &quot;模拟规格即模型规格&quot;">​</a></h3><p>奇性核的离散化会改变短端偏斜的数值。把 hybrid 的近端窗口、时间步、以及 \\(\\xi\\) 在 \\(T\\to 0\\) 的正则化当成「实现细节」而不写进模型卡，等于每个引擎各有一个 rBergomi。障碍、cliquet、VIX 凸性对短核尤其敏感：同一组 \\((H,\\eta,\\rho)\\) 在两种离散下可以给出不同的路径产品价格，香草却都还能对上——识别再次落在非香草上，与 LSV 的弱识别是同一类病。</p><p><span class="marginnote">\\(\\eta\\) 是分数核的水平，不是 Heston 的 vol-of-vol \\(\\sigma\\)。量纲随 \\(H\\) 变：比较「rBergomi 的 \\(\\eta\\) 与 Heston 的 \\(\\sigma\\)」没有意义，能比的是它们产生的短端偏斜与 VIX 凸性。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>欧式没有仿射闭式，校准循环比 Heston 重一个数量级。Wiener 混沌、核回归与深度学习代理可以加速，但生产上仍应保留一条可复现的 hybrid 模拟作为对账金标准。物理测度的 \\(H\\) 与风险中性的 \\(H\\) 不必相同，尽管经验上常接近；中间隔着波动率风险溢价。用历史 \\(H\\)、定价 \\(\\eta\\)，要在报告里写清两个测度。</p><p>有跳时短端 \\(\\xi_0\\) 已混进跳补偿，连续 Volterra 会把跳质量误读成更糙的 \\(H\\) 或更大的 \\(\\eta\\)。跳跃与粗糙可以叠加，识别必须用路径产品或已实现跳检验，不能单靠香草。分数布朗在 \\(H\\neq 1/2\\) 时不能当对冲工具；Delta 对冲的是 \\(S\\)，曲线对冲的是 \\(\\xi\\) 的桶，与经典 Bergomi 相同，只是核变了。</p><p><span class="marginnote">出处不要写成「Gatheral 2018 发明了 rBergomi」。2016 年 Bayer–Friz–Gatheral 是定价与数值；2018 年 Gatheral–Jaisson–Rosenbaum 是尺度律。Mandelbrot–Van Ness 给出 \\(W^H\\)；Comte–Renault 把它接到光滑侧（\\(H\\gt 1/2\\)）。</span></p><p><span class="marginnote">用 rBergomi 给 VIX 定价时，标的是未来三十天方差的平方根。分数核对近端凸性极敏感，Heston 均值回复会系统性低估这一凸性——这是引入粗糙核的交易动机之一，而不只是为了贴两周 25-delta。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>rBergomi 保留 Bergomi 的远期方差鞅，把指数核换成 \\((T-t)^{H-1/2}\\)；今日 \\(\\xi_0\\) 仍来自市场方差曲线。</li><li>欧式与 VIX 靠高斯 Volterra / hybrid 模拟，没有 Heston 式特征函数。</li><li>\\(H\\) 用时间序列锚定，\\(\\eta,\\rho\\) 拟合偏斜；把 \\(H\\) 当普通香草参数会与尺度律冲突。</li><li>一因子分数核可同时服务陡短偏斜与平静长方差，这是相对两因子指数核的结构优势。</li><li>模拟规格（步长、近端窗口、短端正则化）属于模型定义，须与定价引擎绑定。</li><li>出处：Bayer, Friz and Gatheral, <em>Quantitative Finance</em>, 2016；经验尺度见 Gatheral, Jaisson and Rosenbaum, 2018；曲线对象见 Bergomi；对照 Comte and Renault, 1998。</li></ul>',14))])}const c=l(h,[["render",A]]);export{F as __pageData,c as default};
